fn should_log(level: &str) -> bool {
    // Check RUST_LOG env var, simple implementation
    // If RUST_LOG is set, parse it to determine if we should log
    // Original uses tracing with EnvFilter. For simplicity, if RUST_LOG contains level, allow.
    // Levels: error < warn < info < debug < trace
    // We'll support: if RUST_LOG is set to "debug", log debug, info, warn, error
    // If "info", log info, warn, error, etc.
    // If not set, default to info, warn, error (not debug/trace)

    let filter = std::env::var("RUST_LOG").unwrap_or_else(|_| "info".to_string());
    let filter = filter.to_lowercase();

    let level_order = |lvl: &str| match lvl {
        "error" => 0,
        "warn" => 1,
        "info" => 2,
        "debug" => 3,
        "trace" => 4,
        _ => 2,
    };

    let current_level = level_order(&filter);
    let msg_level = level_order(level);

    msg_level <= current_level || filter.contains(level) || filter == "trace" || filter == "debug" && msg_level <= 3
}

