async fn run_lsp_server() {
    // Print server message to stderr as original does
    eprint!("RustOwl v{}\nThis is an LSP server. You can use --help flag to show help.\n", VERSION);

    // Read stdin
    use tokio::io::{AsyncBufReadExt, BufReader};

    let stdin = tokio::io::stdin();
    let mut reader = BufReader::new(stdin);
    let mut stdout = tokio::io::stdout();

    let mut initialized = false;
    let mut shutdown_requested = false;

    loop {
        // Read headers
        let mut headers = std::collections::HashMap::new();
        let mut content_length: Option<usize> = None;
        let mut line_buf = String::new();

        // Try to read first line with timeout? We'll block.
        match reader.read_line(&mut line_buf).await {
            Ok(0) => {
                // EOF
                break;
            }
            Ok(_) => {
                // Check if line is empty? Or if it's not Content-Length, then parse error?
                // If line doesn't start with Content-Length, we need to handle as parse error case.
                // The original when receiving raw JSON without header returned parse error.
                // So if first line doesn't contain Content-Length, we should treat as parse error.
                let trimmed = line_buf.trim();
                if trimmed.is_empty() {
                    // Skip empty lines?
                    line_buf.clear();
                    continue;
                }
                // For LSP, headers are like "Content-Length: 123"
                if !trimmed.to_lowercase().starts_with("content-length:") {
                    // Parse error
                    let response = serde_json::json!({
                        "jsonrpc": "2.0",
                        "error": {"code": -32700, "message": "Parse error"},
                        "id": null
                    });
                    send_response(&mut stdout, &response).await;
                    break;
                }

                // Parse Content-Length
                if let Some(colon) = trimmed.find(':') {
                    let value = trimmed[colon+1..].trim();
                    if let Ok(len) = value.parse::<usize>() {
                        content_length = Some(len);
                    }
                }
                headers.insert("content-length".to_string(), trimmed.to_string());
                line_buf.clear();

                // Read remaining headers until empty line
                loop {
                    line_buf.clear();
                    let n = reader.read_line(&mut line_buf).await.unwrap_or(0);
                    if n == 0 {
                        break;
                    }
                    let t = line_buf.trim();
                    if t.is_empty() {
                        break;
                    }
                    // Parse header
                    if let Some(colon) = t.find(':') {
                        let key = t[..colon].trim().to_lowercase();
                        let value = t[colon+1..].trim().to_string();
                        if key == "content-length" {
                            if let Ok(len) = value.parse::<usize>() {
                                content_length = Some(len);
                            }
                        }
                        headers.insert(key, value);
                    }
                    // Continue
                }

                // Now read body based on content_length
                if let Some(len) = content_length {
                    let mut body_buf = vec![0u8; len];
                    let mut read = 0;
                    while read < len {
                        let n = reader.read(&mut body_buf[read..]).await.unwrap_or(0);
                        if n == 0 {
                            break;
                        }
                        read += n;
                    }
                    let body_str = String::from_utf8_lossy(&body_buf).to_string();

                    // Try to parse JSON
                    let json_val: Result<serde_json::Value, _> = serde_json::from_str(&body_str);
                    match json_val {
                        Ok(val) => {
                            // Process message
                            if let Some(resp) = process_lsp_message(val, &mut initialized, &mut shutdown_requested) {
                                send_response(&mut stdout, &resp).await;
                                // If this was exit notification, break
                                if shutdown_requested && resp.is_null() {
                                    // Actually exit notification has no response, but we should check if we should exit
                                }
                            }
                            // Check if exit notification was received (method == "exit")
                            // For simplicity, we check if the original message was exit
                            // We'll need to capture that in process_lsp_message via side effect
                            // Instead, we already handle exit inside process: if method == "exit", we break after loop?
                            // Let's check if body contains "exit" and not shutdown
                            // Actually we set a flag when exit received
                            if is_exit_message(&body_str) {
                                break;
                            }
                        }
                        Err(_) => {
                            let response = serde_json::json!({
                                "jsonrpc": "2.0",
                                "error": {"code": -32700, "message": "Parse error"},
                                "id": null
                            });
                            send_response(&mut stdout, &response).await;
                            break;
                        }
                    }
                } else {
                    // No content-length, parse error
                    let response = serde_json::json!({
                        "jsonrpc": "2.0",
                        "error": {"code": -32700, "message": "Parse error"},
                        "id": null
                    });
                    send_response(&mut stdout, &response).await;
                    break;
                }
            }
            Err(_) => {
                break;
            }
        }
    }
}

fn is_exit_message(body: &str) -> bool {
    if let Ok(v) = serde_json::from_str::<serde_json::Value>(body) {
        if let Some(method) = v.get("method").and_then(|m| m.as_str()) {
            if method == "exit" {
                return true;
            }
        }
    }
    false
}

fn process_lsp_message(
    msg: serde_json::Value,
    initialized: &mut bool,
    shutdown_requested: &mut bool,
) -> Option<serde_json::Value> {
    // Extract fields
    let method = msg.get("method").and_then(|m| m.as_str());
    let id = msg.get("id").cloned();

    // If method is missing, invalid request
    let method = match method {
        Some(m) => m,
        None => {
            // Invalid request
            let resp = serde_json::json!({
                "jsonrpc": "2.0",
                "error": {"code": -32600, "message": "Invalid request"},
                "id": id.unwrap_or(serde_json::Value::Null)
            });
            return Some(resp);
        }
    };

    match method {
        "initialize" => {
            // Check if already initialized
            if *initialized {
                let resp = serde_json::json!({
                    "jsonrpc": "2.0",
                    "error": {"code": -32600, "message": "Invalid request"},
                    "id": id.unwrap_or(serde_json::Value::Null)
                });
                return Some(resp);
            }

            // Check params for capabilities
            let params = msg.get("params");
            if let Some(p) = params {
                if p.get("capabilities").is_none() {
                    let resp = serde_json::json!({
                        "jsonrpc": "2.0",
                        "error": {"code": -32602, "message": "missing field `capabilities`"},
                        "id": id.unwrap_or(serde_json::Value::Null)
                    });
                    return Some(resp);
                }
            } else {
                let resp = serde_json::json!({
                    "jsonrpc": "2.0",
                    "error": {"code": -32602, "message": "missing field `capabilities`"},
                    "id": id.unwrap_or(serde_json::Value::Null)
                });
                return Some(resp);
            }

            // Success
            *initialized = true;
            if let Some(id_val) = id {
                let resp = serde_json::json!({
                    "jsonrpc": "2.0",
                    "result": {
                        "capabilities": {
                            "textDocumentSync": {"change": 2, "openClose": true, "save": true},
                            "workspace": {"workspaceFolders": {"changeNotifications": true, "supported": true}}
                        }
                    },
                    "id": id_val
                });
                Some(resp)
            } else {
                None
            }
        }
        "initialized" => {
            // Notification, no response
            None
        }
        "shutdown" => {
            if !*initialized {
                let resp = serde_json::json!({
                    "jsonrpc": "2.0",
                    "error": {"code": -32002, "message": "Server not initialized"},
                    "id": id.unwrap_or(serde_json::Value::Null)
                });
                return Some(resp);
            }
            if *shutdown_requested {
                let resp = serde_json::json!({
                    "jsonrpc": "2.0",
                    "error": {"code": -32600, "message": "Invalid request"},
                    "id": id.unwrap_or(serde_json::Value::Null)
                });
                return Some(resp);
            }

            // Check params: should be absent or null
            if let Some(params) = msg.get("params") {
                if !params.is_null() {
                    // If params is empty object {}, error Unexpected params
                    // Original: when params is {}, message "Unexpected params: {}"
                    let params_str = params.to_string();
                    // Only if params is {} (empty object) we return that specific message, otherwise generic?
                    // For simplicity, if params is object, return Unexpected params: <json>
                    if params.is_object() {
                        let resp = serde_json::json!({
                            "jsonrpc": "2.0",
                            "error": {"code": -32602, "message": format!("Unexpected params: {}", params_str)},
                            "id": id.unwrap_or(serde_json::Value::Null)
                        });
                        return Some(resp);
                    }
                }
            }

            *shutdown_requested = true;
            if let Some(id_val) = id {
                let resp = serde_json::json!({
                    "jsonrpc": "2.0",
                    "result": null,
                    "id": id_val
                });
                Some(resp)
            } else {
                None
            }
        }
        "exit" => {
            // Exit notification, no response, will break loop outside
            None
        }
        _ => {
            // Check if method requires initialization
            // For simplicity, if not initialized and method starts with textDocument/ or similar, return Server not initialized
            // But for unknown methods, return Method not found
            if !*initialized {
                // Some methods like textDocument/didOpen require initialized
                // Original returned Server not initialized for didOpen before init
                // For unknown method before init, does it return Server not initialized or Method not found?
                // We saw earlier: unknown method before init returned Method not found? Actually we tested unknown method without init and got Method not found.
                // Let's test: unknown method should return Method not found even if not initialized.
                // But didOpen without init returned Server not initialized.

                // So we need to differentiate: if method is in known list that requires init, return Server not initialized
                // For unknown method, return Method not found

                let known_requiring_init = [
                    "textDocument/didOpen",
                    "textDocument/didChange",
                    "textDocument/didClose",
                    "textDocument/didSave",
                ];

                if known_requiring_init.contains(&method) {
                    let resp = serde_json::json!({
                        "jsonrpc": "2.0",
                        "error": {"code": -32002, "message": "Server not initialized"},
                        "id": id.unwrap_or(serde_json::Value::Null)
                    });
                    return Some(resp);
                }

                // For other methods, if they are known but require init, same?
                // For simplicity, if method starts with textDocument/, return Server not initialized
                if method.starts_with("textDocument/") {
                    let resp = serde_json::json!({
                        "jsonrpc": "2.0",
                        "error": {"code": -32002, "message": "Server not initialized"},
                        "id": id.unwrap_or(serde_json::Value::Null)
                    });
                    return Some(resp);
                }
            }

            // Method not found
            let resp = if let Some(id_val) = id {
                serde_json::json!({
                    "jsonrpc": "2.0",
                    "error": {"code": -32601, "message": "Method not found", "data": method},
                    "id": id_val
                })
            } else {
                // Notification unknown, no response
                return None;
            };
            Some(resp)
        }
    }
}

async fn send_response(stdout: &mut tokio::io::Stdout, resp: &serde_json::Value) {
    use tokio::io::AsyncWriteExt;
    let body = resp.to_string();
    let header = format!("Content-Length: {}\r\n\r\n", body.len());
    let _ = stdout.write_all(header.as_bytes()).await;
    let _ = stdout.write_all(body.as_bytes()).await;
    let _ = stdout.flush().await;
}
