fn log_info(target: &str, msg: &str) {
    if should_log("info") {
        eprintln!("{} INFO  [{}] {}", timestamp(), target, msg);
    }
}
fn log_warn(target: &str, msg: &str) {
    if should_log("warn") {
        eprintln!("{} WARN  [{}] {}", timestamp(), target, msg);
    }
}
fn log_error(target: &str, msg: &str) {
    if should_log("error") {
        eprintln!("{} ERROR [{}] {}", timestamp(), target, msg);
    }
}

fn should_log(level: &str) -> bool {
    let filter = std::env::var("RUST_LOG").unwrap_or_else(|_| "info".to_string());
    let filter = filter.to_lowercase();

    let level_order = |lvl: &str| match lvl {
        "error" => 0,
        "warn" => 1,
        "info" => 2,
        "debug" => 3,
        "trace" => 4,
        _ => 2,
    };

    // If filter contains level string, allow
    // Also respect hierarchy: if filter is "debug", allow debug, info, warn, error
    // If filter is "info", allow info, warn, error, etc.

    // Simple parsing: split by comma, handle
    let current_level = if filter.contains("trace") {
        4
    } else if filter.contains("debug") {
        3
    } else if filter.contains("info") {
        2
    } else if filter.contains("warn") {
        1
    } else if filter.contains("error") {
        0
    } else {
        2 // default info
    };

    let msg_level = level_order(level);

    // If filter contains exact level name, allow, otherwise check hierarchy
    if filter.contains(level) {
        true
    } else {
        msg_level <= current_level
    }
}

