fn should_log(level: &str) -> bool {
    let filter = std::env::var("RUST_LOG").unwrap_or_else(|_| "info".to_string());
    let filter = filter.to_lowercase();
    let level_order = |lvl: &str| match lvl {
        "error" => 0,
        "warn" => 1,
        "info" => 2,
        "debug" => 3,
        "trace" => 4,
        _ => 2,
    };
    let current_level = if filter.contains("trace") {
        4
    } else if filter.contains("debug") {
        3
    } else if filter.contains("info") {
        2
    } else if filter.contains("warn") {
        1
    } else if filter.contains("error") {
        0
    } else {
        2
    };
    let msg_level = level_order(level);
    if filter.contains(level) {
        true
    } else {
        msg_level <= current_level
    }
}

