fn run_lsp_server() {
    eprint!("RustOwl v{}\nThis is an LSP server. You can use --help flag to show help.\n", VERSION);

    use std::io::{BufRead, BufReader, Read};

    let stdin = std::io::stdin();
    let mut reader = BufReader::new(stdin);
    let mut stdout = std::io::stdout();

    let mut initialized = false;
    let mut shutdown_requested = false;

    loop {
        let mut line_buf = String::new();
        match reader.read_line(&mut line_buf) {
            Ok(0) => break,
            Ok(_) => {
                let trimmed = line_buf.trim();
                if trimmed.is_empty() {
                    continue;
                }
                if !trimmed.to_lowercase().starts_with("content-length:") {
                    let response = r#"{"jsonrpc":"2.0","error":{"code":-32700,"message":"Parse error"},"id":null}"#;
                    send_response_sync_str(&mut stdout, response);
                    break;
                }

                let mut content_length: Option<usize> = None;
                if let Some(colon) = trimmed.find(':') {
                    let value = trimmed[colon+1..].trim();
                    if let Ok(len) = value.parse::<usize>() {
                        content_length = Some(len);
                    }
                }

                loop {
                    line_buf.clear();
                    let n = reader.read_line(&mut line_buf).unwrap_or(0);
                    if n == 0 {
                        break;
                    }
                    let t = line_buf.trim();
                    if t.is_empty() {
                        break;
                    }
                    if let Some(colon) = t.find(':') {
                        let key = t[..colon].trim().to_lowercase();
                        let value = t[colon+1..].trim();
                        if key == "content-length" {
                            if let Ok(len) = value.parse::<usize>() {
                                content_length = Some(len);
                            }
                        }
                    }
                }

                if let Some(len) = content_length {
                    let mut body_buf = vec![0u8; len];
                    let mut read = 0;
                    while read < len {
                        match reader.read(&mut body_buf[read..]) {
                            Ok(0) => break,
                            Ok(n) => read += n,
                            Err(_) => break,
                        }
                    }
                    let body_str = String::from_utf8_lossy(&body_buf).to_string();

                    match serde_json::from_str::<serde_json::Value>(&body_str) {
                        Ok(val) => {
                            let is_exit = is_exit_message(&body_str);
                            if let Some(resp_str) = process_lsp_message_str(val, &mut initialized, &mut shutdown_requested) {
                                send_response_sync_str(&mut stdout, &resp_str);
                            }
                            if is_exit {
                                break;
                            }
                        }
                        Err(_) => {
                            let response = r#"{"jsonrpc":"2.0","error":{"code":-32700,"message":"Parse error"},"id":null}"#;
                            send_response_sync_str(&mut stdout, response);
                            break;
                        }
                    }
                } else {
                    let response = r#"{"jsonrpc":"2.0","error":{"code":-32700,"message":"Parse error"},"id":null}"#;
                    send_response_sync_str(&mut stdout, response);
                    break;
                }
            }
            Err(_) => break,
        }
    }
}

fn is_exit_message(body: &str) -> bool {
    if let Ok(v) = serde_json::from_str::<serde_json::Value>(body) {
        if let Some(method) = v.get("method").and_then(|m| m.as_str()) {
            if method == "exit" {
                return true;
            }
        }
    }
    false
}

fn process_lsp_message_str(
    msg: serde_json::Value,
    initialized: &mut bool,
    shutdown_requested: &mut bool,
) -> Option<String> {
    let method = msg.get("method").and_then(|m| m.as_str());
    let id_val = msg.get("id").cloned();
    let id_str = match &id_val {
        Some(v) => v.to_string(),
        None => "null".to_string(),
    };

    let method = match method {
        Some(m) => m,
        None => {
            return Some(format!(r#"{{"jsonrpc":"2.0","error":{{"code":-32600,"message":"Invalid request"}},"id":{}}}"#, id_str));
        }
    };

    match method {
        "initialize" => {
            if *initialized {
                return Some(format!(r#"{{"jsonrpc":"2.0","error":{{"code":-32600,"message":"Invalid request"}},"id":{}}}"#, id_str));
            }

            let params = msg.get("params");
            if let Some(p) = params {
                if p.get("capabilities").is_none() {
                    return Some(format!(r#"{{"jsonrpc":"2.0","error":{{"code":-32602,"message":"missing field `capabilities`"}},"id":{}}}"#, id_str));
                }
            } else {
                return Some(format!(r#"{{"jsonrpc":"2.0","error":{{"code":-32602,"message":"missing field `capabilities`"}},"id":{}}}"#, id_str));
            }

            *initialized = true;
            if id_val.is_some() {
                Some(format!(r#"{{"jsonrpc":"2.0","result":{{"capabilities":{{"textDocumentSync":{{"change":2,"openClose":true,"save":true}},"workspace":{{"workspaceFolders":{{"changeNotifications":true,"supported":true}}}}}}}},"id":{}}}"#, id_str))
            } else {
                None
            }
        }
        "initialized" => None,
        "shutdown" => {
            if !*initialized {
                return Some(format!(r#"{{"jsonrpc":"2.0","error":{{"code":-32002,"message":"Server not initialized"}},"id":{}}}"#, id_str));
            }
            if *shutdown_requested {
                return Some(format!(r#"{{"jsonrpc":"2.0","error":{{"code":-32600,"message":"Invalid request"}},"id":{}}}"#, id_str));
            }

            if let Some(params) = msg.get("params") {
                if !params.is_null() && params.is_object() {
                    let params_str = params.to_string();
                    return Some(format!(r#"{{"jsonrpc":"2.0","error":{{"code":-32602,"message":"Unexpected params: {}"}},"id":{}}}"#, params_str, id_str));
                }
            }

            *shutdown_requested = true;
            if id_val.is_some() {
                Some(format!(r#"{{"jsonrpc":"2.0","result":null,"id":{}}}"#, id_str))
            } else {
                None
            }
        }
        "exit" => None,
        _ => {
            if !*initialized {
                if method.starts_with("textDocument/") {
                    return Some(format!(r#"{{"jsonrpc":"2.0","error":{{"code":-32002,"message":"Server not initialized"}},"id":{}}}"#, id_str));
                }
            }

            if id_val.is_some() {
                Some(format!(r#"{{"jsonrpc":"2.0","error":{{"code":-32601,"message":"Method not found","data":"{}"}},"id":{}}}"#, method, id_str))
            } else {
                None
            }
        }
    }
}

fn send_response_sync_str(stdout: &mut std::io::Stdout, body: &str) {
    let header = format!("Content-Length: {}\r\n\r\n", body.len());
    let _ = stdout.write_all(header.as_bytes());
    let _ = stdout.write_all(body.as_bytes());
    let _ = stdout.flush();
}
