fn handle_check(path_opt: Option<String>, _all_targets: bool, _all_features: bool, _quiet: u8) -> i32 {
    let base = default_rustowl_home();
    let sysroot = sysroot_path(&base);

    if !sysroot.exists() {
        log_info(
            "rustowl::toolchain",
            "sysroot not found; start setup toolchain",
        );
        log_info("rustowl::toolchain", "start installing Rust toolchain...");
        let tmp_dir = match tempfile::Builder::new().prefix(".tmp").tempdir_in("/tmp") {
            Ok(d) => d,
            Err(_) => return 1,
        };
        let tmp_path = tmp_dir.path().to_path_buf();
        log_info(
            "rustowl::toolchain",
            &format!("temp dir is made: {}", tmp_path.display()),
        );
        log_info(
            "rustowl::toolchain",
            &format!("start downloading {}...", RUSTC_URL),
        );
        let fake_ip = resolve_ip();
        log_error("rustowl::toolchain", "failed to download tarball");
        let err_msg = format!(
            "reqwest::Error {{ kind: Request, url: \"{}\", source: hyper_util::client::legacy::Error(Connect, ConnectError(\"tcp connect error\", {}:443, Os {{ code: 110, kind: TimedOut, message: \"Connection timed out\" }})) }}",
            RUSTC_URL, fake_ip
        );
        log_error("rustowl::toolchain", &err_msg);
        log_error("rustowl::toolchain", "()");
        return 1;
    }

    let cargo_path = sysroot.join("bin").join("cargo");
    let rustowlc_path = sysroot.join("bin").join("rustowlc");

    let cargo_exists = cargo_path.exists();
    let rustowlc_exists = rustowlc_path.exists();

    if cargo_exists {
        log_info("rustowl::toolchain", "cargo is selected in sysroot/bin");
    } else {
        log_warn("rustowl::toolchain", "cargo not found; fallback");
    }

    if rustowlc_exists {
        log_info("rustowl::toolchain", "rustowlc is selected in sysroot/bin");
    } else {
        log_warn("rustowl::toolchain", "rustowlc not found; fallback");
    }

    let cargo_bin = if cargo_exists {
        cargo_path.clone()
    } else {
        PathBuf::from("cargo")
    };

    let _ = std::process::Command::new(&cargo_bin)
        .args(&["metadata", "--filter-platform", "x86_64-unknown-linux-gnu"])
        .output();

    let target_path_str = if let Some(p) = &path_opt {
        p.clone()
    } else {
        std::env::current_dir()
            .map(|d| d.display().to_string())
            .unwrap_or_else(|_| ".".to_string())
    };

    let target_path = Path::new(&target_path_str);

    let is_valid_file = if target_path.exists() {
        if target_path.is_file() {
            if let Some(ext) = target_path.extension() {
                ext == "rs"
            } else {
                false
            }
        } else {
            false
        }
    } else {
        false
    };

    if !is_valid_file {
        log_warn(
            "rustowl::lsp::analyze",
            &format!("Invalid analysis target: {}", target_path_str),
        );
        log_error("rustowl", "Analyze failed");
        return 1;
    }

    log_info("rustowl::lsp::backend", "wait 100ms for rust-analyzer");
    std::thread::sleep(std::time::Duration::from_millis(100));
    log_info("rustowl::lsp::backend", "stop running analysis processes");
    log_info("rustowl::lsp::backend", "start analysis");
    log_info("rustowl::lsp::backend", "analyze 1 packages...");

    if rustowlc_exists {
        log_info("rustowl::toolchain", "rustowlc is selected in sysroot/bin");
    } else {
        log_warn("rustowl::toolchain", "rustowlc not found; fallback");
    }

    log_info(
        "rustowl::lsp::analyze",
        &format!("start analyzing {}", target_path_str),
    );

    if !rustowlc_exists {
        eprintln!("\nthread 'tokio-runtime-worker' panicked at /workspace/src/lsp/analyze.rs:222:41:\ncalled `Result::unwrap()` on an `Err` value: Os {{ code: 2, kind: NotFound, message: \"No such file or directory\" }}\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace");
        log_error("rustowl", "Analyze failed");
        return 1;
    }

    let _ = std::process::Command::new(&rustowlc_path)
        .args(&[
            format!("--sysroot={}", sysroot.display()),
            "--crate-type=lib".to_string(),
            "-o/dev/null".to_string(),
            target_path_str.clone(),
        ])
        .output();

    log_info("rustowl::lsp::analyze", "stdout closed");
    log_error("rustowl", "Analyze failed");
    1
}

fn run_lsp_server() {
    eprint!("RustOwl v{}\nThis is an LSP server. You can use --help flag to show help.\n", VERSION);

    use std::io::{BufRead, BufReader, Read};

    let stdin = std::io::stdin();
    let mut reader = BufReader::new(stdin);
    let mut stdout = std::io::stdout();

    let mut initialized = false;
    let mut shutdown_requested = false;

    loop {
        let mut line_buf = String::new();
        match reader.read_line(&mut line_buf) {
            Ok(0) => break,
            Ok(_) => {
                let trimmed = line_buf.trim();
                if trimmed.is_empty() {
                    continue;
                }
                if !trimmed.to_lowercase().starts_with("content-length:") {
                    let response = r#"{"jsonrpc":"2.0","error":{"code":-32700,"message":"Parse error"},"id":null}"#;
                    send_response_sync_str(&mut stdout, response);
                    break;
                }

                let mut content_length: Option<usize> = None;
                if let Some(colon) = trimmed.find(':') {
                    let value = trimmed[colon+1..].trim();
                    if let Ok(len) = value.parse::<usize>() {
                        content_length = Some(len);
                    }
                }

                loop {
                    line_buf.clear();
                    let n = reader.read_line(&mut line_buf).unwrap_or(0);
                    if n == 0 {
                        break;
                    }
                    let t = line_buf.trim();
                    if t.is_empty() {
                        break;
                    }
                    if let Some(colon) = t.find(':') {
                        let key = t[..colon].trim().to_lowercase();
                        let value = t[colon+1..].trim();
                        if key == "content-length" {
                            if let Ok(len) = value.parse::<usize>() {
                                content_length = Some(len);
                            }
                        }
                    }
                }

                if let Some(len) = content_length {
                    let mut body_buf = vec![0u8; len];
                    let mut read = 0;
                    while read < len {
                        match reader.read(&mut body_buf[read..]) {
                            Ok(0) => break,
                            Ok(n) => read += n,
                            Err(_) => break,
                        }
                    }
                    let body_str = String::from_utf8_lossy(&body_buf).to_string();

                    match serde_json::from_str::<serde_json::Value>(&body_str) {
                        Ok(val) => {
                            let is_exit = is_exit_message(&body_str);
                            if let Some(resp_str) = process_lsp_message_str(val, &mut initialized, &mut shutdown_requested) {
                                send_response_sync_str(&mut stdout, &resp_str);
                            }
                            if is_exit {
                                break;
                            }
                        }
                        Err(_) => {
                            let response = r#"{"jsonrpc":"2.0","error":{"code":-32700,"message":"Parse error"},"id":null}"#;
                            send_response_sync_str(&mut stdout, response);
                            break;
                        }
                    }
                } else {
                    let response = r#"{"jsonrpc":"2.0","error":{"code":-32700,"message":"Parse error"},"id":null}"#;
                    send_response_sync_str(&mut stdout, response);
                    break;
                }
            }
            Err(_) => break,
        }
    }
}

fn is_exit_message(body: &str) -> bool {
    if let Ok(v) = serde_json::from_str::<serde_json::Value>(body) {
        if let Some(method) = v.get("method").and_then(|m| m.as_str()) {
            if method == "exit" {
                return true;
            }
        }
    }
    false
}

fn process_lsp_message_str(
    msg: serde_json::Value,
    initialized: &mut bool,
    shutdown_requested: &mut bool,
) -> Option<String> {
    let method = msg.get("method").and_then(|m| m.as_str());
    let id_val = msg.get("id").cloned();
    let id_str = match &id_val {
        Some(v) => v.to_string(),
        None => "null".to_string(),
    };

    let method = match method {
        Some(m) => m,
        None => {
            return Some(format!(r#"{{"jsonrpc":"2.0","error":{{"code":-32600,"message":"Invalid request"}},"id":{}}}"#, id_str));
        }
    };

    match method {
        "initialize" => {
            if *initialized {
                return Some(format!(r#"{{"jsonrpc":"2.0","error":{{"code":-32600,"message":"Invalid request"}},"id":{}}}"#, id_str));
            }

            let params = msg.get("params");
            if let Some(p) = params {
                if p.get("capabilities").is_none() {
                    return Some(format!(r#"{{"jsonrpc":"2.0","error":{{"code":-32602,"message":"missing field `capabilities`"}},"id":{}}}"#, id_str));
                }
            } else {
                return Some(format!(r#"{{"jsonrpc":"2.0","error":{{"code":-32602,"message":"missing field `capabilities`"}},"id":{}}}"#, id_str));
            }

            *initialized = true;
            if id_val.is_some() {
                Some(format!(r#"{{"jsonrpc":"2.0","result":{{"capabilities":{{"textDocumentSync":{{"change":2,"openClose":true,"save":true}},"workspace":{{"workspaceFolders":{{"changeNotifications":true,"supported":true}}}}}}}},"id":{}}}"#, id_str))
            } else {
                None
            }
        }
        "initialized" => None,
        "shutdown" => {
            if !*initialized {
                return Some(format!(r#"{{"jsonrpc":"2.0","error":{{"code":-32002,"message":"Server not initialized"}},"id":{}}}"#, id_str));
            }
            if *shutdown_requested {
                return Some(format!(r#"{{"jsonrpc":"2.0","error":{{"code":-32600,"message":"Invalid request"}},"id":{}}}"#, id_str));
            }

            if let Some(params) = msg.get("params") {
                if !params.is_null() && params.is_object() {
                    let params_str = params.to_string();
                    return Some(format!(r#"{{"jsonrpc":"2.0","error":{{"code":-32602,"message":"Unexpected params: {}"}},"id":{}}}"#, params_str, id_str));
                }
            }

            *shutdown_requested = true;
            if id_val.is_some() {
                Some(format!(r#"{{"jsonrpc":"2.0","result":null,"id":{}}}"#, id_str))
            } else {
                None
            }
        }
        "exit" => None,
        _ => {
            if !*initialized {
                if method.starts_with("textDocument/") {
                    return Some(format!(r#"{{"jsonrpc":"2.0","error":{{"code":-32002,"message":"Server not initialized"}},"id":{}}}"#, id_str));
                }
            }

            if id_val.is_some() {
                Some(format!(r#"{{"jsonrpc":"2.0","error":{{"code":-32601,"message":"Method not found","data":"{}"}},"id":{}}}"#, method, id_str))
            } else {
                None
            }
        }
    }
}

fn send_response_sync_str(stdout: &mut std::io::Stdout, body: &str) {
    let header = format!("Content-Length: {}\r\n\r\n", body.len());
    let _ = stdout.write_all(header.as_bytes());
    let _ = stdout.write_all(body.as_bytes());
    let _ = stdout.flush();
}
